#define MAXN 100005

typedef struct {
    int left_type; // 0 for weight, 1 for rod
    int left_id;   // weight index or rod index
    int right_type;
    int right_id;
    double ratio;  // left length / right length
} Rod;

typedef struct {
    double weight; // weight of the weight object
} Weight;

Rod rods[MAXN];
Weight weights[MAXN];
int n_rods, n_weights;
double min_weight[MAXN];
int visited[MAXN];

double compute_weight(int idx) {
    if (visited[idx]) return min_weight[idx];
    visited[idx] = 1;

    double left_w, right_w;

    // Compute left side weight
    if (rods[idx].left_type == 0) {
        left_w = weights[rods[idx].left_id].weight;
    } else {
        left_w = compute_weight(rods[idx].left_id);
    }

    // Compute right side weight
    if (rods[idx].right_type == 0) {
        right_w = weights[rods[idx].right_id].weight;
    } else {
        right_w = compute_weight(rods[idx].right_id);
    }

    // For balance: left_w * left_length = right_w * right_length
    // ratio = left_length / right_length
    // So left_w * ratio = right_w
    // To minimize total weight, we need to scale both sides to be integers (or multiples)
    // The minimal total weight is achieved by scaling so that both sides are integers
    // and the ratio condition holds.

    // We need left_w * ratio = right_w
    // Let ratio = p/q in simplest terms
    // Then left_w must be multiple of q, right_w must be multiple of p
    // Minimal weights: left_w = q * gcd_scale, right_w = p * gcd_scale
    // But we already have some base weights from children.

    // Actually we need to find minimal integer weights satisfying:
    // left_w * ratio = right_w
    // and left_w >= base_left, right_w >= base_right

    double ratio = rods[idx].ratio;

    // Convert ratio to fraction
    int p, q;
    // ratio = left / right, so left = ratio * right
    // We'll find rational approximation
    double eps = 1e-9;
    int best_p = 1, best_q = 1;
    double best_err = fabs(ratio - 1.0);

    for (int den = 1; den <= 10000; den++) {
        int num = (int)(ratio * den + 0.5);
        double err = fabs(ratio - (double)num/den);
        if (err < best_err) {
            best_err = err;
            best_p = num;
            best_q = den;
        }
    }
    p = best_p;
    q = best_q;

    // We need left_w * p = right_w * q (since left/right = p/q => left*q = right*p)
    // Actually ratio = left_length/right_length = p/q
    // Balance: left_w * left_length = right_w * right_length
    // left_w * p/q = right_w => left_w * p = right_w * q

    // Find minimal scaling factor k such that:
    // left_w >= base_left, right_w >= base_right
    // left_w = k * q, right_w = k * p

    double base_left = left_w;
    double base_right = right_w;

    // Find minimal k (integer) such that k*q >= base_left and k*p >= base_right
    int k_left = (int)ceil(base_left / q);
    int k_right = (int)ceil(base_right / p);
    int k = (k_left > k_right) ? k_left : k_right;

    double new_left = k * q;
    double new_right = k * p;

    min_weight[idx] = new_left + new_right;
    return min_weight[idx];
}

