#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef long long ll;

#define MAXN 205
#define INF ((ll)4e18)

typedef struct {
    int l, r;   // children indices, 0 if weight
    ll a, b;    // ratio: red arm length = a, blue arm length = b
} Rod;

Rod rods[MAXN];
int n;

/*
For a rod with left weight L and right weight R, balance requires:
    L * a = R * b
So total T = L + R must be divisible into:
    L = k * b / g
    R = k * a / g
where g = gcd(a,b), and minimum balanced pair is:
    left base  = b/g
    right base = a/g
    total base = (a+b)/g

If left/right are themselves mobiles, their total weights must be multiples
of their own minimal possible totals. We compute for each node the minimum
possible total weight of that whole submobile.

For a leaf weight, minimum total is 1.

For a rod:
    Let ML = minimum total weight possible on left subtree
        MR = minimum total weight possible on right subtree
    Need left weight = x * (b/g), right weight = x * (a/g)
    with left multiple of ML and right multiple of MR.
So x must satisfy:
    x*(b/g) multiple of ML
    x*(a/g) multiple of MR

Minimum x is lcm( ML / gcd(ML, b/g), MR / gcd(MR, a/g) ).

Then total = x * (a+b)/g.
*/

ll gcdll(ll x, ll y) {
    while (y) {
        ll t = x % y;
        x = y;
        y = t;
    }
    return x;
}

ll lcm_limit(ll x, ll y) {
    ll g = gcdll(x, y);
    __int128 t = (__int128)(x / g) * y;
    if (t > INF) return INF;
    return (ll)t;
}

ll solve_node(int id) {
    if (id == 0) return 1; // simple weight

    ll ML = solve_node(rods[id].l);
    ll MR = solve_node(rods[id].r);

    ll a = rods[id].a, b = rods[id].b;
    ll g = gcdll(a, b);
    ll lb = b / g; // minimal left unit
    ll rb = a / g; // minimal right unit

    ll needL = ML / gcdll(ML, lb);
    ll needR = MR / gcdll(MR, rb);

    ll x = lcm_limit(needL, needR);
    if (x >= INF) return INF;

    __int128 total = (__int128)x * (lb + rb);
    if (total > INF) return INF;
    return (ll)total;
}

int main(void) {
    while (1) {
        if (scanf("%d", &n) != 1) return 0;
        if (n == 0) break;

        for (int i = 1; i <= n; i++) {
            scanf("%lld %lld %d %d", &rods[i].a, &rods[i].b, &rods[i].l, &rods[i].r);
        }

        /*
        The rods form a tree; find the root (rod not appearing as child).
        Child index 0 means a weight.
        */
        int isChild[MAXN];
        memset(isChild, 0, sizeof(isChild));
        for (int i = 1; i <= n; i++) {
            if (rods[i].l > 0) isChild[rods[i].l] = 1;
            if (rods[i].r > 0) isChild[rods[i].r] = 1;
        }

        int root = 1;
        for (int i = 1; i <= n; i++) {
            if (!isChild[i]) {
                root = i;
                break;
            }
        }

        printf("%lld\n", solve_node(root));
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node {
    int left_child, right_child;
    int red_len, blue_len; // lengths to left (red) and right (blue) ends
};

vector<Node> tree;
vector<long long> dp_left, dp_right;

void dfs(int u) {
    if (u == -1) return;
    dfs(tree[u].left_child);
    dfs(tree[u].right_child);

    long long left_weight = 0, right_weight = 0;
    if (tree[u].left_child == -1) {
        left_weight = 1; // direct weight
    } else {
        left_weight = dp_left[tree[u].left_child] + dp_right[tree[u].left_child];
    }
    if (tree[u].right_child == -1) {
        right_weight = 1;
    } else {
        right_weight = dp_left[tree[u].right_child] + dp_right[tree[u].right_child];
    }

    // We need to find minimal total weight for this rod
    // Let a = left_weight, b = right_weight
    // We need to satisfy a * red_len = b * blue_len
    // But we can multiply weights by integer factors
    // Let g = gcd(red_len, blue_len)
    // red_len /= g, blue_len /= g
    // We need a * red_len = b * blue_len
    // So a must be multiple of blue_len, b must be multiple of red_len
    // Minimal a = blue_len * left_weight / gcd(left_weight, blue_len)? Wait
    // Actually we have existing left_weight and right_weight as base weights
    // We can scale them up by integer factors
    // Let k1, k2 be scaling factors for left and right subtrees
    // Then (k1 * left_weight) * red_len = (k2 * right_weight) * blue_len
    // k1 * left_weight * red_len = k2 * right_weight * blue_len
    // Minimal k1, k2 positive integers
    // Let L = left_weight, R = right_weight, r = red_len, b = blue_len
    // k1 * L * r = k2 * R * b
    // k1 / k2 = (R * b) / (L * r)
    // Let num = R * b, den = L * r
    // Simplify fraction: g = gcd(num, den)
    // num /= g, den /= g
    // Then k1 = num, k2 = den
    // But we also need to multiply the subtree weights accordingly

    long long L = left_weight, R = right_weight;
    long long r = tree[u].red_len, b = tree[u].blue_len;

    long long num = R * b;
    long long den = L * r;
    long long g = gcd(num, den);
    num /= g;
    den /= g;

    long long k1 = num;
    long long k2 = den;

    dp_left[u] = k1 * L;
    dp_right[u] = k2 * R;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        tree.resize(n);
        dp_left.assign(n, 0);
        dp_right.assign(n, 0);

        for (int i = 0; i < n; i++) {
            cin >> tree[i].red_len >> tree[i].blue_len;
            string left_str, right_str;
            cin >> left_str >> right_str;

