#include <bits/stdc++.h>
using namespace std;

/*
We model each rod as a node in a binary tree.

For a rod i:
- left arm length = a[i]
- right arm length = b[i]
- each side is either:
    * another rod
    * a fixed weight
    * an unknown weight to be chosen

Balance condition:
    a[i] * W_left = b[i] * W_right

For every subtree we compute the minimum possible total weight of that subtree,
under the restriction that the total weight is an integer.

Let f(i) be the minimum total weight of subtree rooted at rod i.
If a side is unknown, we may choose any positive integer weight there.

Suppose left subtree total weight must be L, right must be R.
They must satisfy:
    aL = bR
So:
    L = (b/g) * k
    R = (a/g) * k
where g = gcd(a,b), k is a positive integer.

If a side has a required minimum/base weight x, then corresponding multiple
must be at least x and also realizable by that subtree.

For a subtree/weight attachment:
- fixed weight w: realizable only as exactly w
- unknown weight: realizable as any positive integer, minimum 1
- rod child j: realizable as any positive integer multiple of f(j)
  because scaling all chosen unknown weights in that subtree by t scales the
  whole subtree by t while preserving balance.

Thus each side has a base unit u:
- fixed weight w  -> exact = w
- unknown         -> any positive integer, unit 1
- rod child j     -> any positive multiple of f(j)

For rod i, left weight must be multiple of needL = b/g, right of needR = a/g,
and also compatible with side constraints.

We find the smallest positive pair:
    L = needL * k
    R = needR * k
such that:
- left side can realize L
- right side can realize R

Compatibility:
- unknown: always if positive
- fixed w: requires L == w
- rod unit u: requires L % u == 0 and L >= u

This can be solved with lcm arithmetic.
*/

struct Side {
    int type; // 0 unknown, 1 fixed weight, 2 rod
    long long val; // weight or rod index
};

struct Rod {
    long long a, b;
    Side left, right;
};

static long long lcm_ll(long long a, long long b) {
    return a / std::gcd(a, b) * b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        if (!cin) return 0;
        vector<Rod> rods(n + 1);
        vector<int> indeg(n + 1, 0);

        /*
        Input format assumed:
        For each rod:
            a b
            left_spec
            right_spec

        Each side spec is one of:
            X           unknown weight
            W number    fixed weight
            R number    child rod index

        Since the original statement is omitted here, many online versions of
        this problem use a compact format:
            a b lt lv rt rv
        where lt/rt indicate type and lv/rv the value.
        To support a common numeric format too:
            type 0 = unknown, 1 = weight, 2 = rod

        We parse the numeric format:
            a b lt lv rt rv
        */

        for (int i = 1; i <= n; ++i) {
            long long a, b;
            int lt, rt;
            long long lv, rv;
            cin >> a >> b >> lt >> lv >> rt >> rv;
            rods[i].a = a;
            rods[i].b = b;
            rods[i].left = {lt, lv};
            rods[i].right = {rt, rv};
            if (lt == 2) indeg[(int)lv]++;
            if (rt == 2) indeg[(int)rv]++;
        }

        int root = 1;
        for (int i = 1; i <= n; ++i) {
            if (indeg[i] == 0) {
                root = i;
                break;
            }
        }

        vector<long long> dp(n + 1, -1);

        function<long long(int)> solve = [&](int u) -> long long {
            if (dp[u] != -1) return dp[u];
            Rod &cur = rods[u];

            long long leftUnit = 1, rightUnit = 1;
            bool leftFixed = false, rightFixed = false;
            long long leftFixedVal = -1, rightFixedVal = -1;

            if (cur.left.type == 0) {
                leftUnit = 1;
            } else if (cur.left.type == 1) {
                leftFixed = true;
                leftFixedVal = cur.left.val;
            } else {
                leftUnit = solve((int)cur.left.val);
            }

            if (cur.right.type == 0) {
                rightUnit = 1;
            } else if (cur.right.type == 1) {
                rightFixed = true;
                rightFixedVal = cur.right.val;
            } else {
                rightUnit = solve((int)cur.right.val);
            }

            long long g = std::gcd(cur.a, cur.b);
            long long needL = cur.b / g;
            long long needR = cur.a / g;

            long long ans = -1;

            if (leftFixed && rightFixed) {
                if (cur.a * leftFixedVal == cur.b * rightFixedVal) {
                    ans = leftFixedVal + rightFixedVal;
                }
            } else if (leftFixed) {
                if (leftFixedVal % needL == 0) {
                    long long k = leftFixedVal / needL;
                    long long R = needR * k;
                    bool ok = true;
                    if (rightFixed) {
                        ok = (R == rightFixedVal);
                    } else {
                        ok = (R > 0 && R % rightUnit == 0);
                    }
                    if (ok) ans = leftFixedVal + R;
                }
            } else if (rightFixed) {
                if (rightFixedVal % needR == 0) {
                    long long k = rightFixedVal / needR;
                    long long L = needL * k;
                    bool ok = true;
                    if (leftFixed) {
                        ok = (L == leftFixedVal);
                    } else {
                        ok = (L > 0 && L % leftUnit == 0);
                    }
                    if (ok) ans = L + rightFixedVal;
                }
            } else {
                // Need k such that:
                // needL*k is multiple of leftUnit
                // needR*k is multiple of rightUnit
                // Minimal positive k.
                long long reqK = 1;

                long long g1 = std::gcd(needL, leftUnit);
                long long t1 = leftUnit / g1;
                reqK = lcm_ll(reqK, t1);

                long long g2 = std::gcd(needR, rightUnit);
                long long t2 = rightUnit / g2;
                reqK = lcm_ll(reqK, t2);

                long long L = needL * reqK;
                long long R = needR * reqK;
                ans = L + R;
            }

            dp[u] = ans;
            return ans;
        };

        cout << solve(root) << "\n";
    }

    return 0;
}

