public class Mobile {
    static class Node {
        int red, blue;
        Node left, right;
        long weight; // only for leaf nodes
        boolean isLeaf;
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static long[] dfs(Node node) {
        // Returns {totalWeight, multiplier} such that totalWeight = multiplier * baseWeight
        if (node.isLeaf) {
            return new long[]{node.weight, 1};
        }
        long[] leftRes = dfs(node.left);
        long[] rightRes = dfs(node.right);
        long leftWeight = leftRes[0];
        long leftMult = leftRes[1];
        long rightWeight = rightRes[0];
        long rightMult = rightRes[1];

        long l = lcm(leftMult, rightMult);
        long leftBase = l / leftMult * leftWeight;
        long rightBase = l / rightMult * rightWeight;

        long totalBase = leftBase * node.red + rightBase * node.blue;
        long multiplier = l * (node.red + node.blue);

        long g = gcd(totalBase, multiplier);
        totalBase /= g;
        multiplier /= g;

        return new long[]{totalBase, multiplier};
    }

    static Node build(Scanner sc) {
        int r = sc.nextInt();
        int b = sc.nextInt();
        Node node = new Node();
        node.red = r;
        node.blue = b;
        if (r == 0 && b == 0) {
            // leaf
            node.isLeaf = true;
            node.weight = 1;
        } else {
            node.isLeaf = false;
            node.left = build(sc);
            node.right = build(sc);
        }
        return node;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            Node root = build(sc);
            long[] res = dfs(root);
            System.out.println(res[0] + res[1] * 0); // total weight = res[0] (since multiplier cancels)
            // Actually total weight is res[0] if we consider base unit as 1
            // But careful: result we want is minimal total integer weight.
            // res[0] is already in smallest integer terms for the whole mobile.
            System.out.println(res[0]);
        }
        sc.close();
    }
}

