public class Main {
    static int[][] rods; // [ratio_a, ratio_b, left, right]

    // returns minimum weight of subtree rooted at rod index (1-based), or 1 if leaf
    static long minWeight(int node) {
        if (node == 0) return 1; // leaf weight
        int a = rods[node][0], b = rods[node][1];
        int left = rods[node][2], right = rods[node][3];
        long minL = minWeight(left);
        long minR = minWeight(right);
        long g = gcd(a, b);
        long ra = a / g, rb = b / g;
        // need leftW = k*rb, rightW = k*ra
        long k = Math.max((minL + rb - 1) / rb, (minR + ra - 1) / ra);
        return k * (ra + rb);
    }

    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
