/*
 * Mobile balancing
 *
 * Each rod has:
 *   - ratio l:r (distance from pivot to red and blue ends)
 *   - red child
 *   - blue child
 *
 * A child is either:
 *   - W x : a fixed weight x
 *   - R k : another rod k
 *
 * Balance condition on a rod:
 *   leftWeight * l == rightWeight * r
 *
 * We may choose weights for unspecified leaves so that the whole mobile balances
 * with minimum total weight. In this formulation, every leaf weight is fixed, and
 * the minimum total weight of each submobile is determined uniquely up to scaling
 * by the balance ratios. The minimum integer total weight is found bottom-up using
 * lcm/gcd.
 *
 * Input format assumed:
 *   t
 *   For each dataset:
 *     n
 *     then n lines, one per rod i = 1..n:
 *       l r  <type1> <val1>  <type2> <val2>
 *
 * where type is either 'W' or 'R'.
 *
 * Output:
 *   minimum total weight of the whole mobile (root is rod 1)
 *
 * This is the standard solution for the classic mobile problem:
 * For each rod, if left and right subweights are a and b, then to satisfy
 *   L*l = R*r
 * we need
 *   L = k*r/g, R = k*l/g where g = gcd(l,r)
 * and each must be a multiple sufficient to contain the corresponding subtree.
 *
 * If left subtree minimum total weight is A and right is B, then choose the
 * smallest k such that:
 *   k*(r/g) is multiple of A
 *   k*(l/g) is multiple of B
 *
 * Equivalently:
 *   leftBase = r/g, rightBase = l/g
 *   k must be multiple of A/gcd(A,leftBase?) -- easier done by lcm:
 *   leftWeight  = smallest multiple of leftBase that is divisible by A
 *   rightWeight = determined by ratio with same k
 *
 * Cleaner:
 *   Let leftUnit = r/g, rightUnit = l/g.
 *   Need leftWeight = leftUnit * m, rightWeight = rightUnit * m
 *   with leftWeight % A == 0 and rightWeight % B == 0.
 *   So m must satisfy:
 *     m % (A / gcd(A,leftUnit)) == 0
 *     m % (B / gcd(B,rightUnit)) == 0
 *   Hence
 *     m = lcm(A/gcd(A,leftUnit), B/gcd(B,rightUnit))
 *   total = (leftUnit + rightUnit) * m
 *
 * For a fixed weight leaf x, subtree weight = x.
 */

public class Main {
    static class Child {
        boolean isRod;
        int val;
        Child(boolean isRod, int val) {
            this.isRod = isRod;
            this.val = val;
        }
    }

    static class Rod {
        long l, r;
        Child left, right;
    }

    static Rod[] rods;
    static long[] memo;

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return Math.abs(a);
    }

    static long lcm(long a, long b) {
        return a / gcd(a, b) * b;
    }

    static long weightOf(Child c) {
        if (!c.isRod) return c.val;
        return solve(c.val);
    }

    static long solve(int idx) {
        if (memo[idx] != -1) return memo[idx];
        Rod rod = rods[idx];

        long A = weightOf(rod.left);
        long B = weightOf(rod.right);

        long g = gcd(rod.l, rod.r);
        long leftUnit = rod.r / g;
        long rightUnit = rod.l / g;

        long needMLeft = A / gcd(A, leftUnit);
        long needMRight = B / gcd(B, rightUnit);

        long m = lcm(needMLeft, needMRight);
        long total = (leftUnit + rightUnit) * m;

        memo[idx] = total;
        return total;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int T = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 0; tc < T; tc++) {
            int n = fs.nextInt();
            rods = new Rod[n + 1];
            for (int i = 1; i <= n; i++) rods[i] = new Rod();

            for (int i = 1; i <= n; i++) {
                Rod rod = rods[i];
                rod.l = fs.nextLong();
                rod.r = fs.nextLong();

                String t1 = fs.next();
                int v1 = fs.nextInt();
                String t2 = fs.next();
                int v2 = fs.nextInt();

                rod.left = new Child(t1.charAt(0) == 'R', v1);
                rod.right = new Child(t2.charAt(0) == 'R', v2);
            }

            memo = new long[n + 1];
            Arrays.fill(memo, -1);

            out.append(solve(1)).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
